package com.careflow.hospital.scheduling;
import jakarta.persistence.*; import java.time.*; import java.util.UUID;
@Entity @Table(name="doctor_schedule_exception") public class DoctorScheduleException {@Id @Column(name="exception_id") private UUID id;@Column(name="doctor_id",nullable=false) private UUID doctorId;@Column(name="exception_date",nullable=false) private LocalDate date;@Column(name="exception_type",nullable=false) private String type;@Column(name="starts_at") private LocalTime startsAt;@Column(name="ends_at") private LocalTime endsAt;@Column(name="slot_duration_minutes") private Integer slotDurationMinutes;private String reason;@Column(name="created_at",nullable=false) private Instant createdAt;protected DoctorScheduleException(){}public DoctorScheduleException(UUID doctorId,LocalDate date,String type,LocalTime start,LocalTime end,Integer duration,String reason){id=UUID.randomUUID();this.doctorId=doctorId;this.date=date;this.type=type;startsAt=start;endsAt=end;slotDurationMinutes=duration;this.reason=reason;createdAt=Instant.now();}public UUID getId(){return id;}public UUID getDoctorId(){return doctorId;}public LocalDate getDate(){return date;}public String getType(){return type;}public LocalTime getStartsAt(){return startsAt;}public LocalTime getEndsAt(){return endsAt;}public Integer getSlotDurationMinutes(){return slotDurationMinutes;}public String getReason(){return reason;}}
